{
  "title": "The Gilded Ruin Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined royal city.",
      "visual_description": "A massive broken gate looms under a twilight sky; crumbling towers flank the entrance. Faded royal banners flutter in the wind.",
      "characters": ["Mira the Map Reader", "Kael the Scout", "Lira the Magic Helper", "Tobin the Sleepy Official", "Zeph the Impassable Walker"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople warn of the cursed towers.",
      "visual_description": "Huddled figures in dirty cloaks point at a spiraling tower with a faint green glow; their faces are gaunt with fear.",
      "characters": ["Mira the Map Reader", "Kael the Scout", "Tobin the Sleepy Official", "Frightened Townspeople"]
    },
    {
      "scene_number": 3,
      "caption": "The scout spots armored patrols near the castle gates.",
      "visual_description": "Kael peers from behind a collapsed wall; three armored figures in black steel march in unison past the inner gate.",
      "characters": ["Kael the Scout", "Armored Patrol"]
    },
    {
      "scene_number": 4,
      "caption": "Lira tests the first magic door with a spell.",
      "visual_description": "Lira extends a glowing hand toward a stone door engraved with runes; the runes pulse in response, casting dancing shadows.",
      "characters": ["Lira the Magic Helper", "Mira the Map Reader"]
    },
    {
      "scene_number": 5,
      "caption": "Tobin accidentally triggers a trap in the courtyard.",
      "visual_description": "Tobin steps on a loose tile; a hidden crossbow bolt flies past his ear as the party ducks.",
      "characters": ["Tobin the Sleepy Official", "Mira the Map Reader", "Kael the Scout", "Lira the Magic Helper"]
    },
    {
      "scene_number": 6,
      "caption": "Zeph crosses a chasm to retrieve a key.",
      "visual_description": "Zeph walks on thin air above a deep fissure, reaching for a glowing key on a pedestal on the far side.",
      "characters": ["Zeph the Impassable Walker", "Mira the Map Reader"]
    },
    {
      "scene_number": 7,
      "caption": "The party enters a throne room filled with illusions.",
      "visual_description": "Holographic figures of past kings sit on a gilded throne; the room shifts and changes layout as they move.",
      "characters": ["Mira the Map Reader", "Kael the Scout", "Lira the Magic Helper", "Tobin the Sleepy Official", "Zeph the Impassable Walker"]
    },
    {
      "scene_number": 8,
      "caption": "A rumor of dragons echoes from a nearby tower.",
      "visual_description": "A distant roar shakes dust from the ceiling; a winged silhouette passes briefly across a high window.",
      "characters": ["Kael the Scout", "Lira the Magic Helper", "Tobin the Sleepy Official"]
    },
    {
      "scene_number": 9,
      "caption": "The party is ambushed by a patrol in an alley.",
      "visual_description": "Armored soldiers step from side passages, swords drawn, trapping the group between stone walls.",
      "characters": ["Armored Patrol", "Mira the Map Reader", "Kael the Scout", "Lira the Magic Helper", "Tobin the Sleepy Official", "Zeph the Impassable Walker"]
    },
    {
      "scene_number": 10,
      "caption": "Lira opens a sealed door with a forbidden chant.",
      "visual_description": "Lira chants in a deep voice; the door's runes flare red and the stone grinds open, revealing a dark staircase.",
      "characters": ["Lira the Magic Helper", "Mira the Map Reader", "Kael the Scout", "Tobin the Sleepy Official", "Zeph the Impassable Walker"]
    },
    {
      "scene_number": 11,
      "caption": "The party finds the prisoner in a cursed tower cell.",
      "visual_description": "A figure in chains sits on a stone floor, surrounded by a circle of glowing glyphs that pulse with a sickly light.",
      "characters": ["The Prisoner", "Mira the Map Reader", "Kael the Scout", "Lira the Magic Helper", "Tobin the Sleepy Official", "Zeph the Impassable Walker"]
    },
    {
      "scene_number": 12,
      "caption": "Tobin picks the lock while Lira disables the glyphs.",
      "visual_description": "Tobin works a set of picks on the manacles while Lira traces counter-runes in the air, sweat on her brow.",
      "characters": ["Tobin the Sleepy Official", "Lira the Magic Helper", "The Prisoner"]
    },
    {
      "scene_number": 13,
      "caption": "The tower begins to collapse as they free the prisoner.",
      "visual_description": "Cracks spider across the walls; dust and stones fall as the party rushes toward the stairwell.",
      "characters": ["The Prisoner", "Mira the Map Reader", "Kael the Scout", "Lira the Magic Helper", "Tobin the Sleepy Official", "Zeph the Impassable Walker"]
    },
    {
      "scene_number": 14,
      "caption": "A dragon lands on the tower roof, blocking the main exit.",
      "visual_description": "A massive red dragon perches atop the crumbling tower, its tail coiling around the parapet, eyes glowing.",
      "characters": ["Dragon", "Mira the Map Reader", "Kael the Scout", "Lira the Magic Helper", "Tobin the Sleepy Official", "Zeph the Impassable Walker", "The Prisoner"]
    },
    {
      "scene_number": 15,
      "caption": "Zeph leads the party across an impossible bridge of light.",
      "visual_description": "Zeph conjures a shimmering bridge of energy from the tower window to a nearby rooftop; the party crosses single file above the city.",
      "characters": ["Zeph the Impassable Walker", "Mira the Map Reader", "Kael the Scout", "Lira the Magic Helper", "Tobin the Sleepy Official", "The Prisoner"]
    },
    {
      "scene_number": 16,
      "caption": "The patrols mass at the main bridge, cutting off escape.",
      "visual_description": "A line of armored soldiers with torches forms across the stone bridge; arrows nocked, shields raised.",
      "characters": ["Armored Patrol", "Dragon (in distance)"]
    },
    {
      "scene_number": 17,
      "caption": "Mira reads an old map to find a hidden bridge passage.",
      "visual_description": "Mira unrolls a parchment under moonlight, tracing a faded route that bypasses the main bridge via a submerged archway.",
      "characters": ["Mira the Map Reader", "Kael the Scout", "Lira the Magic Helper", "Tobin the Sleepy Official", "Zeph the Impassable Walker", "The Prisoner"]
    },
    {
      "scene_number": 18,
      "caption": "The party escapes across the hidden bridge as dawn breaks.",
      "visual_description": "The group wades through shallow water under a low stone arch, emerging on the far bank as the sun rises over the ruined city.",
      "characters": ["Mira the Map Reader", "Kael the Scout", "Lira the Magic Helper", "Tobin the Sleepy Official", "Zeph the Impassable Walker", "The Prisoner"]
    }
  ]
}

